/**
 * Ambient declaration of the TV render bench's virtual module (plan R0-02), generated by
 * `apps/tizen/scripts/bench-atlas.mjs` `shmupRenderBench()` in the bench builds only
 * (`vite.bench.config.ts`) — the game's build never resolves it. Also the bench builds' campaign
 * defines (`./campaign.ts`) and their output and build-id defines (`./output.ts`).
 *
 * @module
 */

/** `VITE_BENCH_CAMPAIGN` of the bench build: the campaign's passes (`'1,2,1,2'`), `''` for none. */
declare const __SHMUP_BENCH_CAMPAIGN__: string;

/** `VITE_BENCH_PAUSE_S` of the bench build: seconds before each campaign pass (default `'30'`). */
declare const __SHMUP_BENCH_PAUSE_S__: string;

/**
 * `VITE_BENCH_OUTPUT` of the bench build, normalised (`'1280x720'` — `./output.ts`
 * `parseBenchOutput`), `''` for the window's backbuffer.
 */
declare const __SHMUP_BENCH_OUTPUT__: string;

/**
 * `VITE_BENCH_SVG` of the bench build, normalised by `./output.ts` `parseBenchSvg`: `'png'` (the
 * default — the PNG atlas pages) or `'e3'` (the SVG arm, `scripts/bench-svg.mjs`).
 */
declare const __SHMUP_BENCH_SVG__: string;

/**
 * The bench build's id (`./output.ts` `benchBuildId`): `__SHMUP_BUILD__`, plus `@<w>x<h>` when the
 * build has an output (`'9e60df2+@1280x720'`), plus `+svg-e3` in the SVG arm.
 */
declare const __SHMUP_BENCH_BUILD_ID__: string;

/**
 * The game-code hash of the bench build (plan v20x BENCSKIP): the 10-hex digest of
 * `scripts/game-code-hash.mjs` over the shipped game's draw inputs, defined by both bench Vite
 * configs — the identity the skip ledger (`./ledger.ts`) and the payloads' pooling key on. A
 * rebuild over unchanged game code carries the same value, so the widget can offer the new rows
 * only; the game build never defines it (the bench is its only consumer).
 */
declare const __SHMUP_GAME_CODE_HASH__: string;

declare module 'virtual:shmup-render-bench' {
  import type { AtlasManifest } from '@shmup/render-pixi';
  /** One density's atlas: the real atlas ×s (nearest-neighbour), its pages next to the page. */
  export interface BenchAtlasModule {
    /** The density factor `s` (1, 1.5, 2.25). */
    readonly density: number;
    /** `x1`, `x1.5`, `x2.25`. */
    readonly label: string;
    /** The scaled manifest (inlined — no `fetch()` on the TV, decision D25). */
    readonly manifest: AtlasManifest;
    /** Page URLs relative to the page (`assets/atlas/bench-x1.5-0.png`, …). */
    readonly pageUrls: readonly string[];
  }
  /** One shipped particle-preset file (`content/fx/*.fx.json`). */
  export interface BenchFxFile {
    /** Path relative to `content/`. */
    readonly path: string;
    /** The parsed JSON document. */
    readonly data: unknown;
  }
  /**
   * One page of the `decode` scenario (plan R1-05 B4, the page model of plan R3-04.M4a,
   * `scripts/bench-decode.mjs`): fetched, decoded and uploaded on the TV, never drawn.
   */
  export interface BenchDecodePageModule {
    /**
     * `standin-zone-a` (with `standin-zone-a-2` right after it when the stand-in group packs onto
     * two pages), `common` or `zone-a`; a bench from before R3-04.M4a also recorded `rgba-2048`
     * and `png8-2048`.
     */
    readonly id: string;
    /** What it stands for. */
    readonly what: string;
    /** Pixels. */
    readonly width: number;
    /** Pixels. */
    readonly height: number;
    /** URL relative to the page (`assets/atlas/decode-standin-zone-a.png`, …). */
    readonly url: string;
  }
  /**
   * The atlas of the run's last page load, `standin-zone` (plan R3-04.M4a): the stand-in build of
   * `scripts/bench-decode.mjs` pruned to the shipped decode pages, so the bench draws one real
   * frame from what it just decoded.
   */
  export interface BenchStandinModule {
    /** The stand-in manifest (inlined — no `fetch()` on the TV, decision D25). */
    readonly manifest: AtlasManifest;
    /** Page URLs relative to the page (the `decode-standin-zone-a*.png` files). */
    readonly pageUrls: readonly string[];
  }
  /** The atlases, in density order. */
  export const atlases: readonly BenchAtlasModule[];
  /** The particle presets. */
  export const fx: readonly BenchFxFile[];
  /** The decode scenario's pages, in the order it measures them. */
  export const decode: readonly BenchDecodePageModule[];
  /** The `standin-zone` load's atlas. */
  export const standin: BenchStandinModule;
  /**
   * One clip of the decode scenario's video rows (plan v20x HARBENCH S8): shipped by the
   * `shmupVideos` plugin from the same table, measured on the R7-VID surface path.
   */
  export interface BenchVideoPageModule {
    /** Clip id (the file's name without the extension). */
    readonly id: string;
    /** What it stands for. */
    readonly what: string;
    /** Pixels (the encoder's frame). */
    readonly width: number;
    /** Pixels. */
    readonly height: number;
    /** URL relative to the page (`assets/video/attract-ambient.mp4`). */
    readonly url: string;
  }
  /** The decode scenario's video clips, in the order it measures them. */
  export const videos: readonly BenchVideoPageModule[];
  /** All five. */
  const bench: {
    readonly atlases: readonly BenchAtlasModule[];
    readonly fx: readonly BenchFxFile[];
    readonly decode: readonly BenchDecodePageModule[];
    readonly standin: BenchStandinModule;
    readonly videos: readonly BenchVideoPageModule[];
  };
  export default bench;
}
